/*  Example: Better F2C conversion table
    Aithor: Peter Brusilovsky
    Modified version of: K&R2, p.12
    Print Fahrenheit-Celsius table with a border
       for fahr = 0, 20, ..., 300; floating point version */

#include <stdio.h>
#define LOWER 0
#define UPPER 300
#define STEP  20
#define TABLETOP "+-------------+\n"

void main () {
    float fahr, celsius;

    fahr = LOWER;
    printf("Fahrenheit to Celsius\nTemperature Conversion\n\n");
    printf(TABLETOP);
    while (fahr <= UPPER) {
        celsius = (5.0 / 9.0) * (fahr - 32.0);
        printf ("| %3.0f  %6.1f |\n", fahr, celsius);
        fahr += STEP;
    }
    printf(TABLETOP);
}
